insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='onkogin'), 'PK-01', 1, 'Anamnesis', 'Anamnesis onkologi komprehensif: gejala konstitusional/organ-spesifik, ECOG, riwayat herediter (BRCA/Lynch), toksisitas terapi, isu fertilitas/kontrasepsi, nyeri-nutrisi-psikososial, red flags; informed consent singkat; ringkasan masalah.', 'Kelengkapan data kunci; identifikasi red flags; ECOG terdokumentasi.', 120, 'encounter anamnesis onkologi mandiri', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='onkogin'), 'PK-02', 2, 'Pemeriksaan Fisik', 'Pemeriksaan umum & onkologi ginekologi (termasuk nodal basin, rektovaginal/EUA bila indikasi) dengan pendamping; aseptik; keselamatan/kenyamanan; dokumentasi.', 'Teknik benar & aman; temuan kunci (nodal/organ infiltration) teridentifikasi; dokumentasi lengkap.', 120, 'pemeriksaan fisik onkologi komprehensif', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='onkogin'), 'PK-03', 3, 'Penentuan Kebutuhan Pemeriksaan Penunjang', 'Seleksi laboratorium, imaging (USG/CT/MRI/PET-CT), penanda tumor, histopatologi/IHC, biomarker (ER/PR, p16, p53, HER2, MMR/MSI, BRCA/HRD, PD-L1); prioritisasi biaya-manfaat; permintaan terstandar.', 'Ketepatan indikasi/prioritas; pemeriksaan tidak perlu minimal; pemesanan tepat waktu.', 80, 'keputusan paket work-up onkologi', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='onkogin'), 'PK-04', 4, 'Interpretasi Hasil Pemeriksaan', 'Integrasi radiologi-patologi-biomarker; penetapan FIGO sementara; baseline RECIST; rekomendasi tindak lanjut.', 'Akurasi interpretasi; konsistensi staging klinis; rekomendasi tindak lanjut tepat.', 80, 'interpretasi terintegrasi', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='onkogin'), 'PK-05', 5, 'Penetapan Diagnosis Kerja dan Banding', 'Problem list; primer vs metastasis/unknown primary/sinkron; pengelompokan risiko; penetapan FIGO; rasionalisasi banding.', 'Akurasi diagnosis kerja; daftar banding relevan; penetapan FIGO konsisten.', 80, 'penetapan diagnosis/staging', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='onkogin'), 'PK-06', 6, 'Perencanaan Terapi (Farmakologis/Nonfarmakologis)', 'Rencana multimodal berbasis NCCN/ESGO/FIGO: urutan operasi-CT-RT/targeted-imuno/hormonal; fertility-sparing bila layak; pencegahan VTE/antiemetik; informed consent; koordinasi MDT.', 'Adherence guideline; kesalahan dosis/kontraindikasi minimal.', 50, 'rencana terapi individual', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='onkogin'), 'PK-07', 7, 'Evaluasi Respon dan Penyesuaian Terapi', 'Penilaian respons RECIST; penilaian toksisitas; modifikasi dosis/jadwal; supportive care.', 'Klasifikasi RECIST tepat; penanganan toksisitas sesuai protokol; tindak lanjut tepat waktu.', 50, 'evaluasi respons/toksisitas', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='onkogin'), 'PK-08', 8, 'Penetapan Prognosis', 'Faktor prognostik (stadium, grade, LVSI, nodal, biomarker/genetik); kelompok risiko; survivorship plan; indikasi paliatif.', 'Estimasi risiko konsisten dengan bukti; komunikasi prognosis jelas; rencana kontrol terdokumentasi.', 20, 'diskusi prognosis & rencana kontrol', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='onkogin'), 'PK-09', 9, 'Dokumentasi Medis dan Komunikasi Hasil', 'Rekam medis onkologi terstruktur (SOAP, staging, biomarker); ringkasan klinis; MDT tumor board; rujukan genetic counseling; breaking bad news; handover (SBAR).', 'Kelengkapan dokumentasi; presentasi MDT efektif; komunikasi hasil tepat waktu.', 150, 'entri/handover terverifikasi', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
insert into clinical_competency_subtargets (program_id, competency_id, nama, kode, target_min) select (select id from programs where kode='onkogin'), id, 'Presentasi MDT', 'mdt', 20 from clinical_competencies where kode='PK-09' and program_id=(select id from programs where kode='onkogin') and not exists (select 1 from clinical_competency_subtargets st join clinical_competencies cc on cc.id=st.competency_id where cc.kode='PK-09' and cc.program_id=(select id from programs where kode='onkogin') and st.nama='Presentasi MDT');
insert into clinical_competency_subtargets (program_id, competency_id, nama, kode, target_min) select (select id from programs where kode='onkogin'), id, 'Breaking bad news', 'breaking_bad_news', 10 from clinical_competencies where kode='PK-09' and program_id=(select id from programs where kode='onkogin') and not exists (select 1 from clinical_competency_subtargets st join clinical_competencies cc on cc.id=st.competency_id where cc.kode='PK-09' and cc.program_id=(select id from programs where kode='onkogin') and st.nama='Breaking bad news');
insert into procedures (program_id, kode, no, nama, target_min, satuan, peran_disyaratkan, syarat_tambahan, perlu_verifikasi) values ((select id from programs where kode='onkogin'), 'PR-01', 1, 'Diagnosis dan manajemen kanker ginekologi', 100, 'kasus baru', 'penanggung jawab utama', 'dengan verifikasi MDT', false) on conflict (program_id, kode) do update set nama=excluded.nama, target_min=excluded.target_min, satuan=excluded.satuan, peran_disyaratkan=excluded.peran_disyaratkan, syarat_tambahan=excluded.syarat_tambahan, perlu_verifikasi=excluded.perlu_verifikasi;
