insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='fer'), 'PK-01', 1, 'Anamnesis', 'Anamnesis terarah pada kelainan diferensiasi seksual, kelainan pubertas, kelainan haid, nyeri panggul kronis, hiperandrogenisme, lama dan faktor risiko infertilitas, riwayat obstetri dan keguguran berulang, teknologi reproduksi berbantu, kebutuhan preservasi fertilitas, keluhan menopause, masalah kontrasepsi, serta kelainan adrenal, tiroid, insufisiensi ovarium prematur, dan gejala sindrom hiperstimulasi ovarium.', 'Lembar evaluasi endokrinologi reproduksi dan infertilitas (wanita & pria) terisi lengkap, kebutuhan terapi dan faktor risiko teridentifikasi; kelengkapan data ≥75%.', 1, 'komponen (ambang kualitas)', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='fer'), 'PK-02', 2, 'Pemeriksaan Fisik', 'Penilaian tanda pertumbuhan seksual sekunder dan kelainan genitalia, tanda hiperandrogen, tanda kelainan tiroid dan adrenal, kelainan anatomik organ reproduksi interna, serta tanda sindrom hiperstimulasi ovarium.', 'Tahap pubertas (kriteria Tanner), tanda hiperandrogenisme, dokumentasi temuan anatomi relevan, faktor prognosis, serta tanda ascites/efusi pleura terdokumentasi; kelengkapan data ≥75%.', 1, 'komponen (ambang kualitas)', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='fer'), 'PK-03', 3, 'Penentuan Pemeriksaan Penunjang', 'Pemilihan USG organ reproduksi, analisis kromosom, histerosalpingografi, pemeriksaan hormon reproduksi (AMH, FSH, LH, estradiol, prolaktin, progesteron, TSH, free T4, kortisol, DHEAS, testosteron, SHBG, insulin, hCG), dan analisis sperma suami.', 'Uji penunjang dipilih sesuai indikasi; kelengkapan data ≥75%.', 1, 'komponen (ambang kualitas)', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='fer'), 'PK-04', 4, 'Interpretasi Hasil', 'Interpretasi jenis kelainan diferensiasi seksual, kelainan pubertas sentral/perifer, etiologi dan keparahan PUA, derajat hiperandrogenisme, jenis anovulasi, fenotip/derajat endometriosis, jenis dan etiologi infertilitas, prognosis TRB, keguguran berulang, preservasi fertilitas, keluhan menopause, kontrasepsi, serta kelainan tiroid, adrenal, insufisiensi ovarium prematur, dan sindrom hiperstimulasi ovarium.', 'Teridentifikasinya etiologi, derajat, rencana terapi/protokol yang sesuai untuk tiap kondisi; kesesuaian interpretasi hasil >75%.', 1, 'komponen (ambang kualitas)', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='fer'), 'PK-05', 5, 'Diagnosis Kerja & Banding', 'Penegakan diagnosis kerja dan banding pada kelainan diferensiasi seksual, kelainan pubertas, amenore, PUA, hiperandrogenisme, SOPK, anovulasi, endometriosis, infertilitas, keguguran berulang, TRB, preservasi fertilitas, menopause, kontrasepsi, serta kelainan adrenal, tiroid, insufisiensi ovarium prematur, dan sindrom hiperstimulasi ovarium.', 'Diagnosis sesuai panduan praktik klinik dengan diagnosis banding dan rencana konfirmasi yang jelas; akurasi diagnosis ≥75% dan rencana konfirmasi ≥75%.', 1, 'komponen (ambang kualitas)', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='fer'), 'PK-06', 6, 'Perencanaan Terapi', 'Penyusunan rencana terapi: penyesuaian gender dan terapi hormon multidisiplin, induksi/stimulasi ovulasi, terapi anti-androgen hormonal/non-hormonal dan bedah, teknologi reproduksi berbantu, inseminasi intrauterin, simpan beku gamet/gonad, terapi hormonal pascamenopause, dan terapi suportif sindrom hiperstimulasi ovarium.', 'Perencanaan multidisiplin bila perlu, pemilihan protokol TRB sesuai panduan, terapi bedah sesuai indikasi; ketepatan terapi >75%.', 1, 'komponen (ambang kualitas)', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='fer'), 'PK-07', 7, 'Evaluasi Respon & Penyesuaian', 'Evaluasi kondisi fisik dan psikis, siklus menstruasi, pengendalian perdarahan dan kualitas hidup, tanda hiperandrogenisme, profil ovulasi, nyeri panggul kronik, perkembangan folikel dan kehamilan, perolehan oosit, angka fertilisasi dan kehamilan, jumlah gamet, keluhan menopause, efek samping kontrasepsi, serta profil hormon sumbu hipotalamus-hipofisis-tiroid dan -adrenal.', 'Jadwal pemantauan sesuai program terapi dan keputusan modifikasi berbasis kriteria objektif; kepatuhan monitoring ≥75%.', 1, 'komponen (ambang kualitas)', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
