insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='fetomaternal'), 'PK-01', 1, 'Anamnesis', 'Riwayat obstetri risiko tinggi: preeklamsia dini/HELLP, IUFD/PTB, PAS, GDM/PGDM, penyakit jantung, autoimun, kelainan darah/metabolik, komorbid kronik, paparan obat/teratogen, kehamilan ganda & chorionicity, paparan infeksi, riwayat imunisasi Rh.', 'Form risiko MFM lengkap; stratifikasi risiko (mild/moderate/severe) terdokumentasi; chorionicity ditentukan sebelum 14 mg pada kembar; rencana pencegahan (aspirin dosis rendah, Ca) bila indikasi.', 1, 'komponen (ambang kualitas)', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='fetomaternal'), 'PK-02', 2, 'Pemeriksaan Fisik', 'Teknik pengukuran tekanan darah akurat (cegah white coat), pemeriksaan jantung/paru, evaluasi edema/refleks/gejala preeklamsia berat, palpasi presentasi/tinggi fundus dan Leopold.', 'Audit teknik pengukuran BP; red flags preeklamsia/HELLP dipantau dan tercatat; dokumentasi presentasi/fundus pada trimester III.', 1, 'komponen (ambang kualitas)', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='fetomaternal'), 'PK-03', 3, 'Penentuan Pemeriksaan Penunjang', 'USG detail target organ, Doppler (UA/MCA/CPR), NST/CTG, BPP, panel lab preeklampsia sesuai penyakit medik penyerta, keputusan NIPT vs amnio/CVS, skrining GDM/PGDM, ekokardiografi maternal bila indikasi.', 'Pemilihan modalitas sesuai pedoman & usia kehamilan; justifikasi NIPT vs diagnostik; skrining GDM pada jendela 24-28 mg.', 1, 'komponen (ambang kualitas)', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='fetomaternal'), 'PK-04', 4, 'Interpretasi Hasil Pemeriksaan', 'Interpretasi biometri (percentile), deteksi kelainan bawaan janin, kriteria FGR vs SGA, indeks Doppler, kategori CTG, dan pengambilan keputusan waktu persalinan.', 'Klasifikasi FGR/SGA benar; identifikasi kelainan bawaan janin; interpretasi CTG akurat; rencana timing persalinan berbasis risiko terdokumentasi.', 1, 'komponen (ambang kualitas)', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='fetomaternal'), 'PK-05', 5, 'Diagnosis Kerja & Banding', 'Penetapan preeklamsia (dengan/tanpa severe features), HELLP, PAS, GDM/PGDM, kelainan janin mayor, diferensial IUGR vs infeksi.', 'Penggunaan kriteria diagnostik sesuai panduan/standar; dokumentasi klasifikasi derajat/stadium bila relevan.', 1, 'komponen (ambang kualitas)', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='fetomaternal'), 'PK-06', 6, 'Perencanaan Terapi', 'Protokol preeklamsia (MgSO4, antihipertensi), steroid maturasi paru, tatalaksana komplikasi & penyakit medis komorbid, timing & rute persalinan, rencana prosedur fetal invasif (amnio/CVS, transfusi, laser TTTS) di pusat kompeten.', 'Pemberian MgSO4 pada preeklampsia berat; antihipertensi target <160/110; tatalaksana multidisiplin; rencana rujukan/pelaksanaan prosedur invasif jelas.', 1, 'komponen (ambang kualitas)', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='fetomaternal'), 'PK-07', 7, 'Evaluasi Respon & Penyesuaian', 'Monitoring BP/urin, serial pertumbuhan & Doppler, NST/BPP, penyesuaian antihipertensi, eskalasi/induksi/persiapan operasi saat kriteria tercapai.', 'Jadwal monitoring sesuai risiko; kriteria eskalasi jelas (mis. non-reassuring CTG, Doppler memburuk); kepatuhan monitoring sesuai jadwal.', 1, 'komponen (ambang kualitas)', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='fetomaternal'), 'PK-08', 8, 'Penetapan Prognosis', 'Risiko prematuritas, IUFD, morbiditas perinatal/maternal, konseling NICU/ICU, rencana contingency.', 'Diskusi risiko jangka pendek/menengah; dokumentasi goals of care; dokumentasi prognosis & rencana kontinjensi pada kasus risiko menengah-tinggi.', 1, 'komponen (ambang kualitas)', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
insert into clinical_competencies (program_id, kode, no, komponen, penjabaran, kriteria_kinerja, target_min, satuan, perlu_verifikasi) values ((select id from programs where kode='fetomaternal'), 'PK-09', 9, 'Dokumentasi & Komunikasi Hasil', 'Template MFM, hasil USG/Doppler terstruktur, informed consent prosedur invasif, kebutuhan NICU & anestesi, registri kelainan janin bila ada.', 'Catatan lengkap & handover SBAR; lampiran gambar/klip kunci USG; kelengkapan dokumentasi dan handover SBAR untuk pasien rawat/operatif.', 1, 'komponen (ambang kualitas)', false) on conflict (program_id, kode) do update set komponen=excluded.komponen, penjabaran=excluded.penjabaran, kriteria_kinerja=excluded.kriteria_kinerja, target_min=excluded.target_min, satuan=excluded.satuan, perlu_verifikasi=excluded.perlu_verifikasi;
